"""Reconcile two source stores from a consistent snapshot, with an evidence trail."""
from collections import defaultdict
import logging
import time

from . import notes
from .quality import finding, graph_findings, normalize, observation_findings
from .storage import RULE_VERSION, database, encode, generations, invalidate, timestamp, transaction

LOG = logging.getLogger("cognyx")
BLOCK_CORRECTION = ("ne pas corriger", "do not correct", "do not normalize", "ne pas normaliser")


def reconcile(directory, run_id="manual"):
    start = time.monotonic()
    with database(directory) as db, transaction(db):
        gen = generations(db)
        raw_rows = [dict(r) for r in db.execute("SELECT * FROM raw_bom_rows ORDER BY row_id")]
        raw_variants = [dict(r) for r in db.execute("SELECT * FROM raw_variants ORDER BY variant_id")]
        raw_notes = [dict(r) for r in db.execute("SELECT * FROM notes.raw_notes ORDER BY note_id")]
        rows, variants, findings, corrections = normalize(raw_rows, raw_variants)
        notes_findings, extracted, normalized_notes = [], {}, []
        note_by_id = {n["note_id"]: n for n in raw_notes}
        if not raw_rows or not raw_notes:
            findings.append(finding("input_completeness", "dataset", None,
                                    "Both BOM and notes are required for complete reconciliation"))
        for note in raw_notes:
            claims, coverage = notes.extract(note)
            extracted[note["note_id"]] = claims
            normalized_notes.append(dict(note_id=note["note_id"], variant_id=note["variant_id"].strip(),
                ref=note["applies_to_ref"].strip(), revision=note["applies_to_revision"].strip(),
                language=note["language"].strip().lower(), text=note["text"], extraction_status=coverage,
                link_status="unlinked"))
            if note["language"].strip().lower() not in {"fr", "en", "mixed"}:
                notes_findings.append(finding("note_metadata", note["note_id"], "language", "Unsupported language label"))
            for field in ("source_document", "variant_id", "applies_to_ref", "applies_to_revision", "text"):
                if not note[field].strip():
                    notes_findings.append(finding("note_metadata", note["note_id"], field, "Required note metadata/text missing", "ERROR"))
            notes_findings.append(finding("extraction_coverage", note["note_id"], "text",
                f"{coverage}: bounded patterns only; remaining prose requires review",
                evidence={"note_ids": [note["note_id"]]}))

        # Collect all alias proposals before accepting any, never last-wins.
        aliases = defaultdict(list)
        for note in raw_notes:
            for claim in extracted[note["note_id"]]:
                if claim["kind"] == "reference_alias":
                    value = claim["value"]
                    scope = (note["variant_id"].strip(), value["alias"], note["applies_to_revision"].strip())
                    aliases[scope].append((note, claim))
        valid_aliases = {}
        for scope, proposals in aliases.items():
            targets = {claim["value"]["target"] for _, claim in proposals}
            target = next(iter(targets))
            variant, alias, revision = scope
            valid = len(targets) == 1 and alias != target and alias.replace("O", "0") == target
            sources = [r for r in rows if (r["variant_id"], r["item_ref"], r["item_revision"]) == scope]
            for note, claim in proposals:
                value = claim["value"]
                valid = valid and note["applies_to_ref"].strip() == alias and value["revision"] == revision
                valid = valid and not any(p in note["text"].lower() for p in BLOCK_CORRECTION)
                valid = valid and bool(sources) and all(r["manufacturer_part_number"] == value["mpn"] for r in sources)
                target_rows = [r for r in rows if r["item_ref"] == target and r["item_revision"] == revision]
                valid = valid and bool(target_rows) and all(r["manufacturer_part_number"] == value["mpn"] for r in target_rows)
            for note, claim in proposals:
                claim["status"] = "supported" if valid else "rejected"
                if not valid:
                    notes_findings.append(finding("alias_evidence", note["note_id"], "text",
                        "Alias is conflicting or lacks matching subject/revision/manufacturer evidence", "ERROR",
                        evidence={"note_ids": [p[0]["note_id"] for p in proposals]}))
            if valid:
                valid_aliases[scope] = (target, [p[0]["note_id"] for p in proposals])

        def correct(row, field, value, rule, note_ids, extra=None):
            old = row[field]
            row[field] = value
            evidence = {"row_ids": [row["row_id"]], "note_ids": note_ids, **(extra or {})}
            corrections.append(dict(row_id=row["row_id"], field=field, original_value=str(old),
                                    normalized_value=str(value), rule=rule, evidence=evidence))
            findings.append(finding(rule, row["row_id"], field, f"Applied evidenced correction: {old} → {value}",
                                    "INFO", "resolved", evidence))

        for row in rows:
            for field, revision_field in (("item_ref", "item_revision"), ("parent_ref", "parent_revision")):
                key = (row["variant_id"], row[field], row[revision_field])
                if key in valid_aliases:
                    target, note_ids = valid_aliases[key]
                    correct(row, field, target, "reference_alias", note_ids)

        # Suggest unproven O/0 pairs, but never merge them by similarity alone.
        identities = {(r["item_ref"], r["item_revision"]) for r in rows}
        for row in rows:
            ref = row["item_ref"]
            if "O" in ref and (ref.replace("O", "0"), row["item_revision"]) in identities and ref.replace("O", "0") != ref:
                findings.append(finding("possible_alias", row["row_id"], "item_ref",
                                        "Possible O/0 spelling collision; no supported alias correction"))

        # Supplier spelling is corrected only for an explicit case-equivalent claim
        # and the note's assembly scope, never used to infer a missing supplier.
        for note in raw_notes:
            for claim in extracted[note["note_id"]]:
                if claim["kind"] != "supplier_alias":
                    continue
                value = claim["value"]
                matching = [r for r in rows if r["variant_id"] == note["variant_id"].strip()
                    and ((r["item_ref"], r["item_revision"]) == (note["applies_to_ref"].strip(), note["applies_to_revision"].strip())
                         or (r["parent_ref"], r["parent_revision"]) == (note["applies_to_ref"].strip(), note["applies_to_revision"].strip()))
                    and r["supplier"] == value["alias"]]
                valid = (value["alias"].casefold() == value["target"].casefold() and bool(matching)
                         and not any(p in note["text"].lower() for p in BLOCK_CORRECTION))
                claim["status"] = "supported" if valid else "rejected"
                if valid:
                    for row in matching:
                        correct(row, "supplier", value["target"], "supplier_alias", [note["note_id"]])

        groups = defaultdict(list)
        raw_by_id = {r["row_id"]: r for r in raw_rows}
        payload_fields = [k for k in rows[0] if k not in {"row_id", "quality_status", "included"}] if rows else []
        for row in rows:
            groups[tuple(row[k] for k in payload_fields) + (raw_by_id[row["row_id"]]["source_export_id"],)].append(row)
        for group in groups.values():
            if len(group) < 2:
                continue
            first = group[0]
            evidence_notes = []
            for note in raw_notes:
                for claim in extracted[note["note_id"]]:
                    if claim["kind"] != "duplicate_occurrence":
                        continue
                    valid = (len(group) == 2 and first["quantity"] == "2" and first["uom"] == "EA"
                        and note["variant_id"].strip() == first["variant_id"]
                        and note["applies_to_ref"].strip() == first["item_ref"]
                        and note["applies_to_revision"].strip() == first["item_revision"]
                        and claim["value"]["parent"] == first["parent_ref"]
                        and not any(p in note["text"].lower() for p in BLOCK_CORRECTION))
                    if valid:
                        claim["status"] = "supported"
                        evidence_notes.append(note["note_id"])
            if evidence_notes:
                for duplicate in group[1:]:
                    correct(duplicate, "included", 0, "duplicate_occurrence", evidence_notes,
                            {"row_ids": [r["row_id"] for r in group]})
            else:
                for row in group:
                    findings.append(finding("duplicate_occurrence", row["row_id"], "included",
                        "Repeated same-parent payload; source evidence is insufficient to suppress it",
                        evidence={"row_ids": [r["row_id"] for r in group]}))

        links = []
        for note in normalized_notes:
            scope = (note["variant_id"], note["ref"], note["revision"])
            method = "exact"
            if scope in valid_aliases:
                note["ref"] = valid_aliases[scope][0]
                method = "evidenced_alias"
            matched = [r for r in rows if (r["variant_id"], r["item_ref"], r["item_revision"]) ==
                       (note["variant_id"], note["ref"], note["revision"])]
            note["link_status"] = "linked" if matched else "unlinked"
            links.extend((note["note_id"], r["row_id"], method) for r in matched)
            if not matched:
                notes_findings.append(finding("note_links", note["note_id"], "ref",
                    "No matching BOM occurrence at this variant/reference/revision", evidence={"note_ids": [note["note_id"]]}))

        findings.extend(graph_findings(rows, variants))
        findings.extend(observation_findings(rows))
        for f in findings:
            if not f["evidence"]:
                f["evidence"] = {"row_ids": [f["entity_id"]]} if f["entity_id"] in raw_by_id else {}
            applicable = [n for n, rid, _ in links if rid == f["entity_id"]]
            if applicable:
                f["evidence"]["note_ids"] = sorted(set(f["evidence"].get("note_ids", []) + applicable))
        flagged = {f["entity_id"] for f in findings if f["status"] == "open" and f["severity"] in {"WARN", "ERROR"}}
        for row in rows:
            row["quality_status"] = "needs_review" if row["row_id"] in flagged else "checked"

        invalidate(db)
        for v in variants:
            db.execute("INSERT INTO variants VALUES (?,?,?,?,?)", tuple(v.values()))
        # Keep malformed-domain rows inspectable; placeholder catalog entries are
        # explicitly flagged, never silently considered real variant metadata.
        for row in rows:
            db.execute("INSERT OR IGNORE INTO variants(variant_id) VALUES (?)", (row["variant_id"],))
            db.execute("INSERT OR IGNORE INTO parts VALUES (?,?)", (row["item_ref"], row["item_revision"]))
            columns = ",".join(row)
            db.execute(f"INSERT INTO bom_rows ({columns}) VALUES ({','.join('?' for _ in row)})", tuple(row.values()))
        for change in corrections:
            db.execute("INSERT INTO corrections(row_id,field,original_value,normalized_value,rule,evidence_json) VALUES (?,?,?,?,?,?)",
                (change["row_id"], change["field"], change["original_value"], change["normalized_value"], change["rule"], encode(change["evidence"])))
        for note in normalized_notes:
            db.execute("INSERT INTO notes.normalized_notes VALUES (?,?,?,?,?,?,?,?)", tuple(note.values()))
        for note_id, claims in extracted.items():
            for c in claims:
                db.execute("INSERT INTO notes.claims(note_id,kind,value_json,span_start,span_end,quote,method,status) VALUES (?,?,?,?,?,?,?,?)",
                           (note_id, c["kind"], encode(c["value"]), c["start"], c["end"], c["quote"], c["method"], c["status"]))
        db.executemany("INSERT INTO notes.links VALUES (?,?,?)", links)
        for schema, issues in (("main", findings), ("notes", notes_findings)):
            for f in issues:
                db.execute(f"INSERT INTO {schema}.findings(rule,severity,status,entity_id,field,message,evidence_json) VALUES (?,?,?,?,?,?,?)",
                           (f["rule"], f["severity"], f["status"], f["entity_id"], f["field"], f["message"], encode(f["evidence"])))
        db.execute("INSERT INTO reconciliation VALUES (1,?,?,?,?,?)", (*gen, RULE_VERSION, run_id, timestamp()))
        errors = sum(f["severity"] == "ERROR" and f["status"] == "open" for f in findings + notes_findings)
        warnings = sum(f["severity"] == "WARN" and f["status"] == "open" for f in findings + notes_findings)
        result = {"bom_rows": len(rows), "notes": len(raw_notes), "corrections": len(corrections),
                  "errors": errors, "warnings": warnings, "generations": gen}
    LOG.info("reconciliation_completed", extra={"details": {**result, "run_id": run_id, "duration_ms": round((time.monotonic()-start)*1000)}})
    return result
"""Dagster assets share the exact same storage/rules used by the CLI."""
import os
from pathlib import Path

import dagster as dg

from .observability import configure
from .pipeline import reconcile
from .storage import RULE_VERSION, database, ingest, status


class LocalStore(dg.ConfigurableResource):
    directory: str = ".local/cognyx"


class BomConfig(dg.Config):
    path: str = "data/bom.csv"
    variants: str = "data/variants.csv"
    override: bool = False


class NotesConfig(dg.Config):
    path: str = "data/technical_notes.csv"
    override: bool = False


def run_step(context, store, function, **kwargs):
    logger = configure(store.directory)
    context.log.info(f"{function.__name__}: local store {Path(store.directory).resolve()}")
    try:
        result = function(store.directory, run_id=context.run_id, **kwargs)
    except Exception:
        logger.exception("pipeline_step_failed", extra={"details": {"run_id": context.run_id, "step": function.__name__}})
        raise
    context.log.info(str(result))
    return result


@dg.asset(group_name="ingestion", description="Exact BOM and variant sources, append-safe and atomically replaceable.")
def bom_raw(context: dg.AssetExecutionContext, config: BomConfig, store: LocalStore):
    result = run_step(context, store, ingest, kind="bom", path=config.path,
                      variants_path=config.variants, override=config.override)
    return dg.MaterializeResult(metadata={"import": dg.MetadataValue.json(result),
                                          "database": dg.MetadataValue.path(str(Path(store.directory).resolve()/"bom.db"))})


@dg.asset(group_name="ingestion", description="Original bilingual technical notes with exact source bytes and provenance.")
def technical_notes_raw(context: dg.AssetExecutionContext, config: NotesConfig, store: LocalStore):
    result = run_step(context, store, ingest, kind="technical-notes", path=config.path, override=config.override)
    return dg.MaterializeResult(metadata={"import": dg.MetadataValue.json(result),
                                          "database": dg.MetadataValue.path(str(Path(store.directory).resolve()/"technical_notes.db"))})


@dg.asset(deps=[bom_raw, technical_notes_raw], group_name="quality", code_version=RULE_VERSION,
          description="Normalize independent source stores, extract bounded note claims, reconcile with auditable evidence.")
def reconciled(context: dg.AssetExecutionContext, store: LocalStore):
    result = run_step(context, store, reconcile)
    return dg.MaterializeResult(metadata={**result, "scope": "Data quality and linked evidence; engineering reuse analysis is not implemented."})


def storage_check(store):
    with database(store.directory) as db:
        errors = []
        for schema in ("main", "notes"):
            errors.extend(f"{schema}: {r[0]}" for r in db.execute(f"PRAGMA {schema}.integrity_check") if r[0] != "ok")
            errors.extend(f"{schema}: {tuple(r)}" for r in db.execute(f"PRAGMA {schema}.foreign_key_check"))
        # SQLite cannot enforce a foreign key from one attached file to another.
        errors.extend(f"Dangling note/BOM link: {r[0]}" for r in db.execute(
            "SELECT l.row_id FROM notes.links l LEFT JOIN raw_bom_rows b ON b.row_id=l.row_id WHERE b.row_id IS NULL"))
    return dg.AssetCheckResult(passed=not errors, metadata={"errors": dg.MetadataValue.json(errors)})


@dg.asset_check(asset=bom_raw, blocking=True, name="sqlite_integrity")
def bom_storage_integrity(store: LocalStore):
    return storage_check(store)


@dg.asset_check(asset=technical_notes_raw, blocking=True, name="sqlite_integrity")
def notes_storage_integrity(store: LocalStore):
    return storage_check(store)


CHECK_RULES = (
    "input_completeness", "identity", "hierarchy", "numeric_values", "units", "missing_values",
    "attribute_conflicts", "possible_alias", "alias_evidence", "reference_alias", "supplier_alias",
    "duplicate_occurrence", "note_metadata", "note_links", "extraction_coverage",
)


@dg.multi_asset_check(specs=[dg.AssetCheckSpec(name=rule, asset="reconciled") for rule in CHECK_RULES])
def data_checks(store: LocalStore):
    snapshot = status(store.directory)
    for rule in CHECK_RULES:
        related = [f for f in snapshot["findings"] if f["rule"] == rule]
        unresolved = [f for f in related if f["status"] == "open"]
        severity = dg.AssetCheckSeverity.ERROR if any(f["severity"] == "ERROR" for f in unresolved) else dg.AssetCheckSeverity.WARN
        yield dg.AssetCheckResult(asset_key="reconciled", check_name=rule, passed=not unresolved,
            severity=severity, metadata={"unresolved": len(unresolved), "resolved": len(related)-len(unresolved),
                "evidence": dg.MetadataValue.json(related), "generations": dg.MetadataValue.json(snapshot["generations"])})


@dg.asset_check(asset=reconciled, blocking=True, name="safe_to_use")
def safe_to_use(store: LocalStore):
    snapshot = status(store.directory)
    return dg.AssetCheckResult(passed=snapshot["reconciliation_current"] and snapshot["unresolved_errors"] == 0,
        severity=dg.AssetCheckSeverity.ERROR, metadata={"errors": snapshot["unresolved_errors"],
        "warnings": snapshot["unresolved_warnings"], "current": snapshot["reconciliation_current"],
        "meaning": "No blocking integrity errors. Open warnings still require engineering/data review."})


@dg.asset(deps=[reconciled], group_name="quality", description="Gated summary; warnings remain visible and never imply engineering approval.")
def quality_summary(store: LocalStore):
    snapshot = status(store.directory)
    # Also guard callers that explicitly select only this asset and omit checks.
    if not snapshot["reconciliation_current"] or snapshot["unresolved_errors"]:
        raise dg.Failure("Reconciliation is stale or has blocking integrity errors. Run reconciliation and inspect findings.")
    return dg.MaterializeResult(metadata={**snapshot["counts"], "warnings": snapshot["unresolved_warnings"],
                                         "status": "needs_review" if snapshot["unresolved_warnings"] else "checked"})


assets = [bom_raw, technical_notes_raw, reconciled, quality_summary]
checks = [bom_storage_integrity, notes_storage_integrity, data_checks, safe_to_use]
bom_job = dg.define_asset_job("ingest_bom", selection=dg.AssetSelection.assets(bom_raw, reconciled, quality_summary))
notes_job = dg.define_asset_job("ingest_technical_notes", selection=dg.AssetSelection.assets(technical_notes_raw, reconciled, quality_summary))
reconcile_job = dg.define_asset_job("reconcile", selection=dg.AssetSelection.assets(reconciled, quality_summary))
all_job = dg.define_asset_job("ingest_all", selection=dg.AssetSelection.all())
defs = dg.Definitions(assets=assets, asset_checks=checks, jobs=[bom_job, notes_job, reconcile_job, all_job],
    resources={"store": LocalStore(directory=os.environ.get("COGNYX_DATA_DIR", ".local/cognyx"))},
    executor=dg.in_process_executor)
"""Local CLI. UI and CLI share persistent Dagster run history and application data."""
import argparse
import json
import os
from pathlib import Path
import subprocess
import sys

from .observability import configure
from .storage import status


def runtime(directory):
    directory = Path(directory).resolve()
    directory.mkdir(parents=True, exist_ok=True)
    home = directory / "dagster"
    home.mkdir(exist_ok=True)
    config = home / "dagster.yaml"
    if not config.exists():
        config.write_text("telemetry:\n  enabled: false\n", encoding="utf-8")
    os.environ["DAGSTER_HOME"] = str(home)
    os.environ["COGNYX_DATA_DIR"] = str(directory)
    configure(directory)
    return directory


def parser():
    root = argparse.ArgumentParser(description="Ingest BOM/notes locally with traceable Dagster data checks.")
    root.add_argument("--data-dir", default=os.environ.get("COGNYX_DATA_DIR", ".local/cognyx"))
    commands = root.add_subparsers(dest="command", required=True)
    server = commands.add_parser("server", help="Start the local Dagster dashboard (foreground).")
    server.add_argument("--port", type=int, default=3000)
    ingest_parser = commands.add_parser("ingest", help="Add inputs; identical records are skipped.")
    inputs = ingest_parser.add_subparsers(dest="kind", required=True)
    for kind in ("bom", "technical-notes"):
        command = inputs.add_parser(kind)
        command.add_argument("path", type=Path)
        command.add_argument("--override", action="store_true", help="Atomically replace this input family; preserve the other family.")
        command.add_argument("--data-dir", default=argparse.SUPPRESS)
        if kind == "bom":
            command.add_argument("--variants", type=Path, required=True)
    for name, help_text in (("status", "Show input counts, freshness and outstanding issues."),
                            ("findings", "Print quality findings with row/note evidence."),
                            ("reconcile", "Rebuild derived data and run checks against current inputs.")):
        commands.add_parser(name, help=help_text)
    for command in commands.choices.values():
        command.add_argument("--data-dir", default=argparse.SUPPRESS)
    return root


def main():
    args = parser().parse_args()
    directory = runtime(args.data_dir)
    if args.command in {"status", "findings"}:
        snapshot = status(directory)
        print(json.dumps(snapshot["findings"] if args.command == "findings" else
                         {k: v for k, v in snapshot.items() if k != "findings"}, ensure_ascii=False, indent=2))
        return
    if args.command == "server":
        command = [str(Path(sys.executable).with_name("dagster")), "dev", "-m", "cognyx_takehome.definitions",
                   "--host", "127.0.0.1", "--port", str(args.port)]
        raise SystemExit(subprocess.call(command))
    # Import after setting env so code-location defaults match this invocation.
    import dagster as dg
    from .definitions import defs
    run_config = {"resources": {"store": {"config": {"directory": str(directory)}}}}
    job_name = "reconcile"
    if args.command == "ingest":
        asset_name = "bom_raw" if args.kind == "bom" else "technical_notes_raw"
        job_name = "ingest_bom" if args.kind == "bom" else "ingest_technical_notes"
        config = {"path": str(args.path.resolve()), "override": args.override}
        if args.kind == "bom":
            config["variants"] = str(args.variants.resolve())
        run_config["ops"] = {asset_name: {"config": config}}
    job = defs.resolve_job_def(job_name)
    with dg.DagsterInstance.get() as instance:
        result = job.execute_in_process(instance=instance, run_config=run_config, raise_on_error=False)
    snapshot = status(directory)
    print(json.dumps({"run_id": result.run_id, "success": result.success,
                      **{k: v for k, v in snapshot.items() if k != "findings"}}, ensure_ascii=False, indent=2))
    if not result.success:
        raise SystemExit(1)
"""Local JSON event logs with bounded rotation; no raw note text in logs."""
import json
import logging
from logging.handlers import RotatingFileHandler
from pathlib import Path

from .storage import timestamp


class JsonFormatter(logging.Formatter):
    def format(self, record):
        event = {"timestamp": timestamp(), "level": record.levelname, "event": record.getMessage(),
                 **getattr(record, "details", {})}
        if record.exc_info:
            event["exception"] = self.formatException(record.exc_info)
        return json.dumps(event, ensure_ascii=False, default=str)


def configure(directory):
    path = Path(directory).resolve() / "logs" / "ingestion.jsonl"
    path.parent.mkdir(parents=True, exist_ok=True)
    logger = logging.getLogger("cognyx")
    logger.setLevel(logging.INFO)
    # Dagster may call multiple assets in one process. Avoid duplicate handlers.
    for handler in list(logger.handlers):
        if getattr(handler, "baseFilename", None) == str(path):
            return logger
        logger.removeHandler(handler)
        handler.close()
    handler = RotatingFileHandler(path, maxBytes=2_000_000, backupCount=3, encoding="utf-8")
    handler.setFormatter(JsonFormatter())
    logger.addHandler(handler)
    logger.propagate = False
    return logger

